PREFIX ref: <http://w3id.org/brick/ref#>
SELECT ?point ?tsid WHERE {
  ?point https://brickschema.org/schema/Brick#hasLocation <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z03> .
